SELECT CASE WHEN stores.city IN ('Bangkok', 'Berlin') THEN 'tier_1' ELSE 'other' END AS city_group, SUM(inventory.quantity) AS total_quantity, AVG(inventory.quantity) AS avg_quantity FROM inventory INNER JOIN stores ON inventory.store_id = stores.id GROUP BY CASE WHEN stores.city IN ('Bangkok', 'Berlin') THEN 'tier_1' ELSE 'other' END ORDER BY avg_quantity DESC, city_group LIMIT 1
